class Solution:
    def reorderList(self, head):
        nodes = []
        cur = head
        while cur:
            nodes.append(cur)
            cur = cur.next

        i, j = 0, len(nodes) - 1
        dummy = ListNode()
        tail = dummy
        while i <= j:
            tail.next = nodes[i]
            tail = tail.next
            i += 1
            if i <= j:
                tail.next = nodes[j]
                tail = tail.next
                j -= 1
        tail.next = None

