class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def reorderList(self, head):
        stack = []
        cur = head
        while cur:
            stack.append(cur)
            cur = cur.next

        cur = head
        for _ in range(len(stack) // 2):
            tail = stack.pop()
            nxt = cur.next
            cur.next = tail
            tail.next = nxt
            cur = nxt
        if cur:
            cur.next = None

